DIRS={1:(0,1),2:(0,-1),3:(1,0),6:(-1,0)}
def ray(inp,H,W,col):
    r,c=next((r,c) for r in range(H) for c in range(W) if inp[r][c]==col)
    dr,dc=DIRS[col]; cells=[]; k=0
    while True:
        rr,cc=r+dr*k,c+dc*k
        if not(0<=rr<H and 0<=cc<W): break
        cells.append((rr,cc)); k+=1
    return cells
