def solve(inp):
    H,W=len(inp),len(inp[0])
    g=[row[:] for row in inp]
    rays=[]
    for r in range(H):
        for c in range(W):
            col=inp[r][c]
            if col: rays.append((r,c,col))
    # ray cells: k=1..color+1 ; paths for crossing detection = k=1..color+1
    paths={}
    info=[]
    for r,c,col in rays:
        dr,dc=DIRS[col]; L=col+1
        cells=[(r+dr*k,c+dc*k) for k in range(1,L+1)]
        info.append((cells,col,r,c))
        paths[(r,c,col)]=(set(cells),cells)
    # crossings: cells on paths of >=2 distinct rays
    hits=set()
    for i,(cells_,col,_,_) in enumerate(info):
        S=paths[(info[i][2],info[i][3],col)][0]
        for j,(cells_j,col_j,r_j,c_j) in enumerate(info):
            if i!=j and paths[(r_j,c_j,col_j)][0]&S:
                hits|=paths[(r_j,c_j,col_j)][0]&S
    for x,y in hits: g[x][y]=4
    # tails from each crossing: down-left diagonal, paint 4 on zeros until edge/nonzero
    for x,y in hits:
        rr,cc=x+1,y-1
        while 0<=rr<H and 0<=cc<W and g[rr][cc]==0:
            g[rr][cc]=4; rr+=1; cc-=1
    for cells,col,r,c in info:
        end=cells[-1]
        if col==1:
            rr,cc=r-1,c+2
            if 0<=rr<H and 0<=cc<W and g[rr][cc]==0: g[rr][cc]=col
        else:
            if g[end[0]][end[1]]==0: g[end[0]][end[1]]=col
    return g
